def diskSphereConeBlock (ρ r : ℝ) : Matrix (Fin 2) (Fin 2) ℝ :=
  let s := Real.sqrt (1 - r ^ 2)
  !![2 * r ^ 2 - 1, 4 * ρ * r;
    2 * s * r, 2 * ρ * s - 2 * ρ * r ^ 2 / s]

